package middleware
import("testing";"strings";"net/http/httptest";"github.com/DATA-DOG/go-sqlmock";"github.com/jmoiron/sqlx";"github.com/gofiber/fiber/v2";"sikapj-backend/internal/auth";"sikapj-backend/internal/config")
func TestForcedPasswordAndRevokedSession(t *testing.T){for _,tt:=range []struct{path string;must bool;version int;want int}{{"/api/admin/pegawai",true,0,403},{"/api/auth/profile",true,0,200},{"/api/auth/password",true,0,200},{"/api/admin/pegawai",false,1,401}}{t.Run(tt.path,func(t *testing.T){db,m,_:=sqlmock.New();defer db.Close();cfg:=&config.Config{JWTSecret:strings.Repeat("x",32),JWTExpirationHours:1};token,_:=auth.GenerateJWTToken(1,"admin","ADMIN","",cfg);m.ExpectQuery("SELECT .*FROM sikapj.users").WillReturnRows(sqlmock.NewRows([]string{"is_active","must_change_password","session_version"}).AddRow(true,tt.must,tt.version));a:=fiber.New();a.Use(AuthRequired(cfg,sqlx.NewDb(db,"sqlmock")));a.All("/*",func(c *fiber.Ctx)error{return c.SendStatus(200)});method:="GET";if tt.path=="/api/auth/password"{method="PUT"};r:=httptest.NewRequest(method,tt.path,nil);r.Header.Set("Authorization","Bearer "+token);res,e:=a.Test(r);if e!=nil{t.Fatal(e)};defer res.Body.Close();if res.StatusCode!=tt.want{t.Fatalf("got %d want %d",res.StatusCode,tt.want)}})}}
